const GEMINI_SYSTEM_INSTRUCTION = `Ти — інтелектуальний планувальник нагадувань та розкладу для Telegram-бота календаря.
Твоє завдання — проаналізувати текст повідомлення від користувача та сформувати ОДНЕ АБО ДЕКІЛЬКА нагадувань.

ПРАВИЛА РОЗПІЗНАВАННЯ:
1. КІЛЬКА НАГАДУВАНЬ: Якщо користувач перелічує кілька справ або пунктів розкладу (наприклад: "завтра о 10 нарада, а в п'ятницю о 18 здати звіт") — створи окремий об'єкт для КОЖНОЇ події у масиві reminders. Якщо вказано одну справу — поверни масив з 1 елементом.
2. Встановлюй status="SUCCESS", якщо розпізнано хоча б одне нагадування або завдання, та вкажи message.
3. Встановлюй status="OUT_OF_SCOPE" ТІЛЬКИ якщо повідомлення абсолютно не містить жодного завдання чи наміру спланувати справу (наприклад: "яка погода", "хто ти", "розкажи анекдот", "привіт як справи").
4. ДАТА ТА ЧАС: Обчисли точну дату (YYYY-MM-DD) та час (HH:MM) для кожної події відносно currentDateTime.
   - "завтра", "післязавтра", "у п'ятницю", "через 2 години" — визнач точну календарну дату.
   - Якщо час не вказано взагалі — став 10:00.
5. ПІДЗАВДАННЯ: Якщо користувач називає перелік дій (наприклад: "купити молоко, хліб, сир") — розбий їх на масив items.
6. КАТЕГОРІЯ: За замовчуванням "main" (або відповідна, якщо підходить за контекстом: work, personal, study тощо).
7. Мова завжди українська.`;

const RESPONSE_SCHEMA = {
  type: "OBJECT",
  properties: {
    status: {
      type: "STRING",
      enum: ["SUCCESS", "OUT_OF_SCOPE", "ERROR"],
      description: "SUCCESS якщо розпізнано завдання, OUT_OF_SCOPE якщо сторонній запит."
    },
    message: {
      type: "STRING",
      description: "Коротке пояснення українською мовою."
    },
    reminders: {
      type: "ARRAY",
      description: "Список сформованих нагадувань",
      items: {
        type: "OBJECT",
        properties: {
          title: { type: "STRING", description: "Назва справи" },
          dateStr: { type: "STRING", description: "Дата YYYY-MM-DD" },
          timeStr: { type: "STRING", description: "Час HH:MM" },
          category: { type: "STRING", description: "Категорія (main, work тощо)" },
          remindBefore: { type: "INTEGER", description: "За скільки хвилин нагадати (0, 15, 30)" },
          repeatType: {
            type: "STRING",
            enum: ["none", "daily", "weekdays", "weekly", "monthly"],
            description: "Тип повторення"
          },
          items: {
            type: "ARRAY",
            items: { type: "STRING" },
            description: "Підзавдання або пункти списку"
          }
        },
        required: ["title", "dateStr", "timeStr"]
      }
    }
  },
  required: ["status", "message"]
};

export interface AiParsedResult {
  status: 'SUCCESS' | 'OUT_OF_SCOPE' | 'ERROR';
  message: string;
  reminders?: Array<{
    title: string;
    dateStr: string;
    timeStr: string;
    category?: string;
    remindBefore?: number;
    repeatType?: string;
    items?: string[];
  }>;
}

export async function parseTelegramReminderWithAi(
  text: string,
  context: { now: string; categories?: any[]; templates?: any[] }
): Promise<AiParsedResult> {
  const geminiKey =
    Deno.env.get('GEMINI_API_KEY') || 'AIzaSyDnD6HQAJzrrxv_Nuv3BOYbXzi1Uufc_eQ';
  if (!geminiKey) {
    console.error('GEMINI_API_KEY is not configured in environment');
    return {
      status: 'ERROR',
      message: 'GEMINI_API_KEY не налаштовано на сервері',
    };
  }

  const promptPayload = {
    userInput: text,
    currentDateTime: context.now,
    availableCategories: context.categories || [],
    availableTemplates: context.templates || [],
  };

  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiKey}`;

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ role: 'user', parts: [{ text: JSON.stringify(promptPayload) }] }],
      systemInstruction: {
        role: 'system',
        parts: [{ text: GEMINI_SYSTEM_INSTRUCTION }],
      },
      generationConfig: {
        responseMimeType: 'application/json',
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.1,
      },
    }),
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Gemini API error ${response.status}: ${errText}`);
  }

  const geminiData = await response.json();
  const rawContent = geminiData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!rawContent) {
    throw new Error('Порожня відповідь від Gemini API');
  }

  return JSON.parse(rawContent) as AiParsedResult;
}

import { sendBotMessage } from '../telegram.ts';
import { getSupabaseClient } from '../db.ts';

export async function generateAndSaveCode(chatId: string | number, user: any) {
  const supabase = getSupabaseClient();
  const code = Math.floor(100000 + Math.random() * 900000).toString();
  const expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString();

  await supabase.from('auth_codes').delete().eq('telegram_id', String(chatId));

  const photoUrl = user?.username ? `https://t.me/i/userpic/320/${user.username}.jpg` : '';

  const { error } = await supabase.from('auth_codes').insert({
    code,
    telegram_id: String(chatId),
    first_name: user?.first_name || '',
    username: user?.username || '',
    photo_url: photoUrl,
    expires_at: expiresAt,
  });

  if (error) {
    console.error('Failed to insert auth code:', error);
    return null;
  }
  return code;
}

export async function sendAuthCode(
  chatId: string | number,
  user: any,
  botToken: string,
  siteUrl: string
) {
  const code = await generateAndSaveCode(chatId, user);
  if (!code) {
    await sendBotMessage(
      botToken,
      chatId,
      '❌ Не вдалося створити код. Спробуйте ще раз через хвилину.',
      siteUrl
    );
    return;
  }

  const replyText =
    `🔐 <b>Ваш одноразовий код для входу:</b>\n\n` +
    `👉 <code>${code}</code> 👈\n\n` +
    `⏱ Дійсний 10 хвилин.\n` +
    `Введіть його на сайті або натисніть кнопку нижче:`;

  await sendBotMessage(botToken, chatId, replyText, siteUrl, [
    [{ text: '🚀 Увійти на сайті в 1 клік', url: `${siteUrl}/?auth=${code}` }],
  ]);
}

import { sendBotMessage } from '../telegram.ts';

const SENTRY_DSN_KEY = 'a42e147c09623a08e739b75addce6227';
const SENTRY_PROJECT_ID = '4512286175461456';
const SENTRY_ENVELOPE_URL = `https://o4512286173626368.ingest.de.sentry.io/api/${SENTRY_PROJECT_ID}/envelope/?sentry_version=7&sentry_key=${SENTRY_DSN_KEY}`;

export async function handleBugReportCommand(
  chatId: number | string,
  message: any,
  botToken: string,
  siteUrl: string
): Promise<void> {
  const from = message.from || {};
  const text = (message.text || message.caption || '').trim();
  const photoList = message.photo;

  // Очищаємо текст від команд
  let reportText = text
    .replace(/^\/(?:bug|feedback|помилка|відгук)(?:@\w+)?/i, '')
    .trim();

  // Якщо користувач надіслав просто /bug без тексту і без фото
  if (!reportText && (!photoList || photoList.length === 0)) {
    await sendBotMessage(
      botToken,
      chatId,
      `📸 <b>Звіт про помилку або відгук</b>\n\n` +
      `Ви можете надіслати сюди будь-який <b>скріншот із коментарем</b> (наприклад, знімок консолі, меню або проблеми) або просто текст із командою <code>/bug ваш опис</code>.\n\n` +
      `Всі звіти разом зі скріншотами автоматично надсилаються розробникам у Sentry!`,
      siteUrl
    );
    return;
  }

  if (!reportText) {
    reportText = 'Скріншот без текстового опису з Telegram-бота';
  }

  try {
    const eventId = crypto.randomUUID().replace(/-/g, '');
    const sentAt = new Date().toISOString();
    const userName =
      [from.first_name, from.last_name].filter(Boolean).join(' ') ||
      from.username ||
      `User ${from.id}`;
    const userContact = from.username ? `@${from.username}` : `tg:${from.id}`;

    let photoBytes: Uint8Array | null = null;
    let photoFileName = 'telegram_screenshot.jpg';

    if (Array.isArray(photoList) && photoList.length > 0) {
      const bestPhoto = photoList[photoList.length - 1];
      const getFileRes = await fetch(
        `https://api.telegram.org/bot${botToken}/getFile?file_id=${bestPhoto.file_id}`
      );
      const fileData = await getFileRes.json();
      if (fileData?.ok && fileData.result?.file_path) {
        const fileUrl = `https://api.telegram.org/file/bot${botToken}/${fileData.result.file_path}`;
        const fileBuffer = await fetch(fileUrl).then((r) => r.arrayBuffer());
        photoBytes = new Uint8Array(fileBuffer);
        const ext = fileData.result.file_path.split('.').pop() || 'jpg';
        photoFileName = `telegram_${bestPhoto.file_unique_id || 'photo'}.${ext}`;
      }
    }

    const header = JSON.stringify({ event_id: eventId, sent_at: sentAt });
    const itemHeader = JSON.stringify({ type: 'feedback', content_type: 'application/json' });
    const itemPayload = JSON.stringify({
      contexts: {
        feedback: {
          message: reportText,
          name: `${userName} (Telegram Bot)`,
          contact_email: userContact,
        },
      },
      tags: {
        source: 'telegram_bot',
        telegram_id: String(from.id),
      },
    });

    const encoder = new TextEncoder();
    let bodyBytes: Uint8Array;

    if (photoBytes) {
      const attachHeader = JSON.stringify({
        type: 'attachment',
        length: photoBytes.byteLength,
        filename: photoFileName,
        content_type: 'image/jpeg',
        attachment_type: 'event.attachment',
      });

      const part1 = encoder.encode(`${header}\n${itemHeader}\n${itemPayload}\n${attachHeader}\n`);
      const part3 = encoder.encode('\n');

      bodyBytes = new Uint8Array(part1.byteLength + photoBytes.byteLength + part3.byteLength);
      bodyBytes.set(part1, 0);
      bodyBytes.set(photoBytes, part1.byteLength);
      bodyBytes.set(part3, part1.byteLength + photoBytes.byteLength);
    } else {
      bodyBytes = encoder.encode(`${header}\n${itemHeader}\n${itemPayload}\n`);
    }

    const sentryRes = await fetch(SENTRY_ENVELOPE_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-sentry-envelope' },
      body: bodyBytes,
    });

    if (sentryRes.ok) {
      await sendBotMessage(
        botToken,
        chatId,
        `✅ <b>Звіт про помилку успішно надіслано!</b>\n\n` +
        `📝 <b>Опис:</b> ${reportText.slice(0, 150)}${reportText.length > 150 ? '...' : ''}\n` +
        (photoBytes ? `🖼 <b>Скріншот:</b> додано (${(photoBytes.byteLength / 1024).toFixed(1)} КБ)\n` : '') +
        `🆔 <b>ID звернення:</b> <code>${eventId}</code>\n\n` +
        `Розробники повідомлені та вже розглядають проблему. Дякуємо!`,
        siteUrl
      );
    } else {
      console.error('Sentry feedback envelope error:', sentryRes.status, await sentryRes.text());
      await sendBotMessage(
        botToken,
        chatId,
        `⚠️ Не вдалося зареєструвати звіт у системі Sentry. Спробуйте пізніше.`,
        siteUrl
      );
    }
  } catch (err) {
    console.error('Failed to handle bug report:', err);
    await sendBotMessage(
      botToken,
      chatId,
      `⚠️ Сталася помилка при відправці звіту. Спробуйте пізніше.`,
      siteUrl
    );
  }
}

import { escapeHtml } from '../utils.ts';
import { sendGroupMessage } from '../telegram.ts';
import { getSupabaseClient } from '../db.ts';
import { recordTopic, isSenderAdmin } from '../teams.ts';

export async function handleBindCommand(
  chatId: string | number,
  threadId: number | undefined,
  text: string,
  user: any,
  botToken: string,
  incomingMessageId?: number | null
) {
  const parts = text.split(/\s+/);
  const categoryRaw = parts[1]?.trim();
  const teamId = `team_${chatId}`;
  const supabase = getSupabaseClient();

  if (!categoryRaw) {
    const helpMsg =
      `💡 <b>Прив'язка теми до категорії нагадувань:</b>\n\n` +
      `Введіть <code>/bind назва_категорії</code> у потрібній гілці чату.\n\n` +
      `Наприклад: <code>/bind робота</code> або <code>/bind навчання</code>.\n` +
      `Після цього всі нагадування з цією категорією надсилатимуться сюди!`;
    await sendGroupMessage(botToken, chatId, helpMsg, threadId, [], incomingMessageId);
    return;
  }

  const isAdmin = await isSenderAdmin(supabase, teamId, user, botToken, chatId);
  if (!isAdmin) {
    await sendGroupMessage(
      botToken,
      chatId,
      '⚠️ Тільки адміністратори команди можуть прив\'язувати теми до категорій.',
      threadId,
      [],
      incomingMessageId
    );
    return;
  }

  const cleanCategory = categoryRaw
    .toLowerCase()
    .replace('#', '')
    .replace(/[^\p{L}\p{N}_-]/gu, '')
    .slice(0, 50);

  if (!cleanCategory) {
    await sendGroupMessage(
      botToken,
      chatId,
      '⚠️ Некоректна назва категорії. Вкажіть, наприклад: <code>/bind робота</code>',
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  await supabase.from('team_category_topics').upsert(
    {
      team_id: teamId,
      category: cleanCategory,
      thread_id: threadId || 0,
      updated_at: new Date().toISOString(),
    },
    { onConflict: 'team_id,category' }
  );

  if (threadId) {
    await recordTopic(supabase, teamId, threadId, cleanCategory);
  }

  const targetTopicText = threadId ? 'цю тему' : 'головний чат';
  const reply =
    `📌 Категорію <b>#${cleanCategory}</b> успішно прив'язано до ${targetTopicText}!\n\n` +
    `Тепер усі командні нагадування цієї категорії надсилатимуться сюди.`;
  await sendGroupMessage(botToken, chatId, reply, threadId, [], incomingMessageId);
}

export async function handleTopicCommand(
  chatId: string | number,
  threadId: number | undefined,
  text: string,
  user: any,
  botToken: string,
  incomingMessageId?: number | null
) {
  if (!threadId) {
    await sendGroupMessage(
      botToken,
      chatId,
      '⚠️ Цю команду потрібно викликати всередині конкретної теми форуму!',
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  const parts = text.split(/\s+/);
  parts.shift();
  const topicName = parts.join(' ').trim();
  const teamId = `team_${chatId}`;
  const supabase = getSupabaseClient();

  const isAdmin = await isSenderAdmin(supabase, teamId, user, botToken, chatId);
  if (!isAdmin) {
    await sendGroupMessage(
      botToken,
      chatId,
      '⚠️ Тільки адміністратори команди можуть реєструвати нові теми.',
      threadId,
      [],
      incomingMessageId
    );
    return;
  }

  if (!topicName) {
    await sendGroupMessage(
      botToken,
      chatId,
      '💡 Вкажіть назву для цієї теми:\n<code>/topic Назва теми</code>',
      threadId,
      [],
      incomingMessageId
    );
    return;
  }

  await recordTopic(supabase, teamId, threadId, topicName);
  await sendGroupMessage(
    botToken,
    chatId,
    `🏷️ Тему зареєстровано як <b>«${escapeHtml(topicName)}»</b>!\nВона вже доступна для вибору в календарі.`,
    threadId,
    [],
    incomingMessageId
  );
}

