  const text =
    `👥 <b>Ваші підключені групи (${lines.length}):</b>\n\n` +
    lines.join('\n\n') +
    `\n\n💡 <i>Натисніть на групу нижче, щоб відкрити її календар:</i>`;

  await sendBotMessage(botToken, chatId, text, siteUrl, teamButtons);
}

