Deno.serve(async (req: Request) => {
  if (req.method !== 'POST') return new Response('OK', { status: 200 });

  if (WEBHOOK_SECRET) {
    const incomingSecret = req.headers.get('x-telegram-bot-api-secret-token');
    if (incomingSecret !== WEBHOOK_SECRET) {
      console.warn('Unauthorized webhook invocation: secret token mismatch');
      return new Response(JSON.stringify({ error: 'Unauthorized: invalid secret token' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      });
    }
  }

  if (!BOT_TOKEN) {
    console.error('TELEGRAM_BOT_TOKEN is not configured in Supabase secrets');
    return new Response(JSON.stringify({ error: 'TELEGRAM_BOT_TOKEN is not configured' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  try {
    const update = await req.json();

    // 1. Callback query handling
    if (update?.callback_query) {
      const cq = update.callback_query;
      const chatId = cq.message?.chat?.id || cq.from?.id;

      if (cq.data === 'get_code' && chatId) {
        await answerCallbackQuery(BOT_TOKEN, cq.id);
        await sendAuthCode(chatId, cq.from, BOT_TOKEN, SITE_URL);
      } else if (cq.data === 'my_groups' && chatId) {
        await answerCallbackQuery(BOT_TOKEN, cq.id);
        await handleUserGroupsCommand(chatId, BOT_TOKEN, SITE_URL);
      } else if (cq.data.startsWith('done_')) {
        const reminderId = cq.data.replace('done_', '');
        const supabase = getSupabaseClient();
        await supabase.from('reminders').update({ is_sent: true }).eq('id', reminderId);
        await answerCallbackQuery(BOT_TOKEN, cq.id, '✅ Нагадування виконано!');
        if (cq.message?.chat?.id && cq.message?.message_id) {
          await deleteTelegramMessage(BOT_TOKEN, cq.message.chat.id, cq.message.message_id);
        }
      } else if (cq.data.startsWith('snooze_')) {
        const reminderId = cq.data.replace('snooze_', '');
        const supabase = getSupabaseClient();
        const snoozeDate = new Date(Date.now() + 15 * 60 * 1000).toISOString();
        await supabase
          .from('reminders')
          .update({ remind_at: snoozeDate, is_sent: false })
          .eq('id', reminderId);
        await answerCallbackQuery(BOT_TOKEN, cq.id, '💤 Відкладено на 15 хв!');
      } else if (cq.data.startsWith('cancel_')) {
        const reminderId = cq.data.replace('cancel_', '');
        const supabase = getSupabaseClient();
        await supabase
          .from('reminders')
          .delete()
          .eq('id', reminderId)
          .eq('user_id', String(chatId));
        await answerCallbackQuery(BOT_TOKEN, cq.id, '🗑 Нагадування скасовано!');
        if (cq.message?.chat?.id && cq.message?.message_id) {
          await editTelegramMessage(
            BOT_TOKEN,
            cq.message.chat.id,
            cq.message.message_id,
            '❌ <i>Нагадування було успішно скасовано.</i>'
          );
        }
      } else {
        await answerCallbackQuery(BOT_TOKEN, cq.id);
      }

      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 2. Chat member updates (new user joined group)
    if (update?.chat_member) {
      const cm = update.chat_member;
      const chat = cm.chat;
      const isGroup = chat?.type === 'group' || chat?.type === 'supergroup';
      if (isGroup && cm.new_chat_member?.user && !cm.new_chat_member.user.is_bot) {
        const supabase = getSupabaseClient();
        const teamId = await ensureTeamExists(supabase, chat, cm.from?.id);
        const status = cm.new_chat_member.status;
        if (status === 'member' || status === 'administrator' || status === 'creator') {
          await recordTeamMember(
            supabase,
            teamId,
            cm.new_chat_member.user,
            status === 'administrator' || status === 'creator'
          );
        }
      }
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 3. Bot chat member status updates (bot promoted/demoted/kicked)
    if (update?.my_chat_member) {
      const mcm = update.my_chat_member;
      const chat = mcm.chat;
      const isGroup = chat?.type === 'group' || chat?.type === 'supergroup';
      if (isGroup) {
        await handleMyChatMemberUpdate(mcm, BOT_TOKEN, SITE_URL);
      }
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const message = update?.message;
    if (!message || !message.chat) return new Response('OK', { status: 200 });

    const chatId = message.chat.id;
    const chatType = message.chat.type;
    const isGroupChat = chatType === 'group' || chatType === 'supergroup';
    const text = (message.text || '').trim();
    const lowerText = text.toLowerCase();
    const threadId = message.message_thread_id;

    // 4. Group Chat Processing
    if (isGroupChat) {
      const supabase = getSupabaseClient();

      // Telegram upgrade: звичайна група мігрувала у супергрупу
      if (message.migrate_to_chat_id) {
        const oldTeamId = `team_${chatId}`;
        const newTeamId = `team_${message.migrate_to_chat_id}`;
        await supabase.from('team_members').update({ team_id: newTeamId }).eq('team_id', oldTeamId);
        await supabase.from('reminders').update({ team_id: newTeamId }).eq('team_id', oldTeamId);
        await supabase.from('team_categories').update({ team_id: newTeamId }).eq('team_id', oldTeamId);
        await supabase.from('team_topics').update({ team_id: newTeamId }).eq('team_id', oldTeamId);
        await supabase.from('team_category_topics').update({ team_id: newTeamId }).eq('team_id', oldTeamId);
        await supabase.from('teams').delete().eq('id', oldTeamId);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      const teamId = await ensureTeamExists(supabase, message.chat, message.from?.id);

      if (message.from && !message.from.is_bot) {
        await recordTeamMember(supabase, teamId, message.from);
      }

      if (Array.isArray(message.new_chat_members)) {
        for (const nm of message.new_chat_members) {
          if (!nm.is_bot) {
            await recordTeamMember(supabase, teamId, nm);
          }
        }
      }

      if (message.forum_topic_created) {
        await recordTopic(supabase, teamId, threadId, message.forum_topic_created.name);
      } else if (threadId) {
        await recordTopic(supabase, teamId, threadId, '');
      }

      if (lowerText.startsWith('/bind')) {
        await handleBindCommand(chatId, threadId, text, message.from, BOT_TOKEN, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      if (lowerText.startsWith('/topic')) {
        await handleTopicCommand(chatId, threadId, text, message.from, BOT_TOKEN, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      if (lowerText.startsWith('/sync')) {
        await handleSyncCommand(chatId, threadId, message.chat, BOT_TOKEN, SITE_URL, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      if (lowerText.startsWith('/addmember') || lowerText.startsWith('/додати')) {
        await handleAddMemberCommand(chatId, threadId, text, message.from, BOT_TOKEN, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      if (
        lowerText.startsWith('/team') ||
        lowerText.startsWith('/calendar') ||
        lowerText.startsWith('/календар')
      ) {
        await handleTeamCommand(chatId, threadId, BOT_TOKEN, SITE_URL, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      if (lowerText.startsWith('/groups') || lowerText.startsWith('/групи')) {
        const botStatus = await getBotChatStatus(BOT_TOKEN, chatId);
        const statusBadge = botStatus.isAdmin
          ? `✅ <b>Адміністратор</b> (повний доступ до тем)`
          : `⚠️ <b>Звичайний учасник</b> (призначте адміном для доступу до тем!)`;
        const reply =
          `ℹ️ <b>Статус бота в цьому чаті:</b> ${statusBadge}\n\n` +
          `📋 Щоб переглянути <b>всі ваші підключені групи</b>, перейдіть в особисті повідомлення з ботом:`;
        const keyboard = [
          [{ text: '💬 Переглянути всі мої групи', url: `https://t.me/reminderveter_bot?start=groups` }],
        ];
        await sendGroupMessage(BOT_TOKEN, chatId, reply, threadId, keyboard, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5. Private Chat Commands
    // 5.0 Bug report / feedback command or photo report
    const isBugReport =
      lowerText.startsWith('/bug') ||
      lowerText.startsWith('/feedback') ||
      lowerText.startsWith('/помилка') ||
      lowerText.startsWith('/відгук') ||
      lowerText === 'баг' ||
      lowerText === 'відгук' ||
      (message.photo &&
        (lowerText.includes('баг') ||
          lowerText.includes('помилка') ||
          lowerText.includes('відгук') ||
          lowerText.includes('bug') ||
          lowerText.includes('feedback') ||
          lowerText.startsWith('/bug')));

    if (isBugReport) {
      await handleBugReportCommand(chatId, message, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.1 Auth code requests
    const isCodeRequest =
      lowerText.startsWith('/code') ||
      lowerText.startsWith('/login') ||
      lowerText.startsWith('/start login') ||
      lowerText.startsWith('/start code') ||
      lowerText === 'код' ||
      text === '🔑 Код для входу';

    if (isCodeRequest) {
      await sendAuthCode(chatId, message.from, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.2 User groups & bot admin status check
    const isGroupsRequest =
      lowerText.startsWith('/groups') ||
      lowerText.startsWith('/teams') ||
      lowerText.startsWith('/групи') ||
      lowerText.startsWith('/команди') ||
      lowerText.startsWith('/start groups') ||
      lowerText === 'групи' ||
      lowerText === 'команди' ||
      lowerText === 'мої групи' ||
      text === '👥 Мої групи та статус бота';

    if (isGroupsRequest) {
      await handleUserGroupsCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.3 Today command
    if (lowerText === '/today' || lowerText === '/сьогодні' || lowerText === 'сьогодні') {
      await handleTodayCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.4 Tomorrow command
    if (lowerText === '/tomorrow' || lowerText === '/завтра' || lowerText === 'завтра') {
      await handleTomorrowCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.5 Week schedule command
    if (lowerText === '/week' || lowerText === '/тиждень' || lowerText === 'тиждень') {
      await handleWeekCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.6 Help command
    if (lowerText === '/help' || lowerText === '/довідка' || lowerText === 'допомога') {
      await sendHelp(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    // 5.7 Intelligent AI Reminder Planner or Direct Photo Feedback
    if (text) {
      await handleAiReminderMessage(chatId, text, message.from, BOT_TOKEN, SITE_URL);
    } else if (message.photo && message.photo.length > 0) {
      await handleBugReportCommand(chatId, message, BOT_TOKEN, SITE_URL);
    } else {
      await sendWelcome(chatId, message.from, BOT_TOKEN, SITE_URL);
    }

    return new Response(JSON.stringify({ ok: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    console.error('Webhook error:', err);
    return new Response('OK', { status: 200 });
  }
});

import { escapeHtml } from './utils.ts';
import { getBotChatStatus } from './telegram.ts';

export async function ensureTeamExists(supabase: any, chat: any, createdBy?: string | number) {
  const teamId = `team_${chat.id}`;
  const isForum = Boolean(chat.is_forum);
  const { data: existing } = await supabase
    .from('teams')
    .select('id, is_forum, title')
    .eq('id', teamId)
    .maybeSingle();

  if (!existing) {
    await supabase.from('teams').insert({
      id: teamId,
      telegram_chat_id: String(chat.id),
      title: chat.title || 'Команда',
      is_forum: isForum,
      created_by: createdBy ? String(createdBy) : '',
      default_role: 'editor',
    });
  } else if (existing.is_forum !== isForum || existing.title !== (chat.title || 'Команда')) {
    await supabase
      .from('teams')
      .update({ is_forum: isForum, title: chat.title || 'Команда' })
      .eq('id', teamId);
  }
  return teamId;
}

export async function recordTeamMember(supabase: any, teamId: string, user: any, forceAdmin = false) {
  if (!user || !user.id) return;
  const userId = String(user.id);
  const cleanUsername = (user.username || '').replace(/^@/, '').toLowerCase();

  let { data: existing } = await supabase
    .from('team_members')
    .select('id, role, telegram_id, first_name, username')
    .eq('team_id', teamId)
    .eq('telegram_id', userId)
    .maybeSingle();

  // Якщо користувача ще не було за ID, перевіряємо чи адмін додав його за @username
  if (!existing && cleanUsername) {
    const { data: placeholder } = await supabase
      .from('team_members')
      .select('id, role, telegram_id, first_name, username')
      .eq('team_id', teamId)
      .ilike('username', cleanUsername)
      .maybeSingle();

    if (placeholder) {
      existing = placeholder;
    }
  }

  if (!existing) {
    await supabase.from('team_members').insert({
      team_id: teamId,
      telegram_id: userId,
      first_name: user.first_name || '',
      username: (user.username || '').replace(/^@/, ''),
      role: forceAdmin ? 'admin' : 'editor',
    });
  } else {
    const cleanUsername = (user.username || '').replace(/^@/, '');
    const newFirstName = user.first_name || '';
    const shouldPromoteAdmin = forceAdmin && existing.role !== 'admin';

    // Оновлюємо рядок ЛИШЕ якщо змінилося ім'я, юзернейм або роль, щоб не спамити PATCH у базу
    const hasDataChanged =
      existing.first_name !== newFirstName ||
      existing.username !== cleanUsername ||
      existing.telegram_id !== userId ||
      shouldPromoteAdmin;

    if (hasDataChanged) {
      const updates: any = {
        telegram_id: userId,
        first_name: newFirstName,
        username: cleanUsername,
        updated_at: new Date().toISOString(),
      };
      if (shouldPromoteAdmin) {
        updates.role = 'admin';
      }
      await supabase
        .from('team_members')
        .update(updates)
        .eq('id', existing.id);
    }
  }
}

export async function syncChatAdmins(supabase: any, botToken: string, chat: any) {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/getChatAdministrators`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chat.id }),
    });
    const data = await res.json();
    if (data.ok && Array.isArray(data.result)) {
      const teamId = `team_${chat.id}`;
      for (const admin of data.result) {
        if (admin.user && !admin.user.is_bot) {
          await recordTeamMember(supabase, teamId, admin.user, true);
        }
      }
    }
  } catch (err) {
    console.error('Failed to sync chat admins:', err);
  }
}

export async function recordTopic(supabase: any, teamId: string, threadId: number, name: string) {
  if (!threadId) return;
  if (!name) {
    const { data: existing } = await supabase
      .from('team_topics')
      .select('name')
      .eq('team_id', teamId)
      .eq('thread_id', threadId)
      .maybeSingle();
    if (existing && existing.name) {
      return;
    }
  }
  await supabase.from('team_topics').upsert(
    {
      team_id: teamId,
      thread_id: threadId,
      name: name || `Тема #${threadId}`,
      updated_at: new Date().toISOString(),
    },
    { onConflict: 'team_id,thread_id' }
  );
}

export async function deleteTeamData(supabase: any, teamId: string) {
  try {
    await supabase.from('reminders').delete().eq('team_id', teamId);
    await supabase.from('team_category_topics').delete().eq('team_id', teamId);
    await supabase.from('team_topics').delete().eq('team_id', teamId);
    await supabase.from('team_members').delete().eq('team_id', teamId);
    await supabase.from('team_categories').delete().eq('team_id', teamId);
    await supabase.from('teams').delete().eq('id', teamId);
  } catch (err) {
    console.error(`Failed to delete team data for ${teamId}:`, err);
  }
}

export async function getUserTeamsWithRoles(supabase: any, userId: string) {
  const { data: memberRows } = await supabase
    .from('team_members')
    .select('team_id, role, teams(*)')
    .eq('telegram_id', userId)
    .neq('role', 'blocked');

  const { data: createdTeams } = await supabase
    .from('teams')
    .select('*')
    .eq('created_by', userId);

  const teamMap = new Map<string, { team: any; role: string }>();

  (memberRows || []).forEach((row: any) => {
    const t = Array.isArray(row.teams) ? row.teams[0] : row.teams;
    if (t && t.id) {
      teamMap.set(t.id, { team: t, role: row.role || 'editor' });
    }
  });

  (createdTeams || []).forEach((ct: any) => {
    if (!teamMap.has(ct.id)) {
      teamMap.set(ct.id, { team: ct, role: 'admin' });
    }
  });

  return Array.from(teamMap.values());
}

export function formatTeamStatusItem(
  item: { team: any; role: string },
  chatStatus: { isAdmin: boolean; status: string },
  index: number,
  siteUrl: string
) {
  const { team, role } = item;
  const botStatusBadge = chatStatus.isAdmin
    ? `✅ <b>Адміністратор</b> <i>(все працює ідеально)</i>`
    : `⚠️ <b>Звичайний учасник</b> <i>(потрібно призначити адміном!)</i>`;

  const roleName = role === 'admin' ? 'Адмін' : role === 'editor' ? 'Редактор' : 'Переглядач';
  const forumBadge = team.is_forum ? ' 💬 <i>(форум з темами)</i>' : '';
  const warningLine = !chatStatus.isAdmin
    ? `\n   ❗ <i>Telegram приховує повідомлення від бота, доки він не стане адміном чату.</i>`
    : '';

  const line =
    `<b>${index + 1}. «${escapeHtml(team.title || 'Команда')}»</b>${forumBadge}\n` +
    `   🤖 Статус бота: ${botStatusBadge}\n` +
    `   👤 Ваша роль: <b>${roleName}</b>${warningLine}`;

  const button = [
    { text: `📅 Відкрити «${team.title || 'Команда'}»`, url: `${siteUrl}/?team=${team.id}` },
  ];

  return { line, button };
}

export async function isSenderAdmin(
  supabase: any,
  teamId: string,
  user: any,
  botToken: string,
  chatId: string | number
): Promise<boolean> {
  if (!user || !user.id) return false;
  const userId = String(user.id);

  // 1. Check in team_members table
  const { data: member } = await supabase
    .from('team_members')
    .select('role')
    .eq('team_id', teamId)
    .eq('telegram_id', userId)
    .maybeSingle();

  if (member?.role === 'admin') return true;

  // 2. Check in teams.created_by
  const { data: team } = await supabase
    .from('teams')
    .select('created_by')
    .eq('id', teamId)
    .maybeSingle();

  if (team?.created_by === userId) return true;

  // 3. Fallback: check Telegram getChatMember
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/getChatMember`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, user_id: Number(userId) }),
    });
    const data = await res.json();
    if (data.ok && (data.result.status === 'administrator' || data.result.status === 'creator')) {
      await supabase
        .from('team_members')
        .upsert(
          {
            team_id: teamId,
            telegram_id: userId,
            first_name: user.first_name || '',
            username: (user.username || '').replace(/^@/, ''),
            role: 'admin',
          },
          { onConflict: 'team_id,telegram_id' }
        );
      return true;
    }
  } catch {}

  return false;
}

import { getSupabaseClient } from './db.ts';

export async function deleteTelegramMessage(
  botToken: string,
  chatId: string | number,
  messageId: string | number
): Promise<boolean> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/deleteMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, message_id: Number(messageId) }),
    });
    const data = await res.json();
    return !!data?.ok;
  } catch (err) {
    console.warn(`Failed to delete message ${messageId} in chat ${chatId}:`, err);
    return false;
  }
}

export async function sendBotMessage(
  botToken: string,
  chatId: string | number,
  text: string,
  siteUrl: string,
  extraRows: any[] = []
) {
  const keyboard = [
    [{ text: '📅 Відкрити Календар (Mini App)', web_app: { url: siteUrl } }],
    ...extraRows,
  ];
  await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text,
      parse_mode: 'HTML',
      reply_markup: { inline_keyboard: keyboard },
    }),
  });
}

export async function sendGroupMessage(
  botToken: string,
  chatId: string | number,
  text: string,
  threadId?: number | null,
  extraRows: any[] = [],
  incomingMessageId?: number | null
): Promise<any> {
  const body: any = {
    chat_id: chatId,
    text,
    parse_mode: 'HTML',
  };
  if (threadId && Number(threadId) > 0) {
    body.message_thread_id = Number(threadId);
  }
  if (extraRows.length > 0) {
    body.reply_markup = { inline_keyboard: extraRows };
  }
  const res = await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

  const data = await res.json();

  if (data?.ok && data.result?.message_id) {
    const botMsgId = data.result.message_id;
    const delaySec = 30;

    // 1. Негайний фоновий таймер на 30 секунд для миттєвого видалення
    const scheduleImmediateDeletion = async () => {
      await new Promise((resolve) => setTimeout(resolve, delaySec * 1000));
      await deleteTelegramMessage(botToken, chatId, botMsgId);
      if (incomingMessageId) {
        await deleteTelegramMessage(botToken, chatId, incomingMessageId);
      }
    };

    // EdgeRuntime.waitUntil підтримується у середовищі Supabase / Deno Edge
    if (typeof (globalThis as any).EdgeRuntime?.waitUntil === 'function') {
      (globalThis as any).EdgeRuntime.waitUntil(scheduleImmediateDeletion());
    } else {
      scheduleImmediateDeletion().catch((err) =>
        console.warn('Background deletion error:', err)
      );
    }

    // 2. Збереження в таблицю bot_ephemeral_messages для резервного cron-видалення
    try {
      const supabase = getSupabaseClient();
      const deleteAt = new Date(Date.now() + delaySec * 1000).toISOString();
      const inserts: any[] = [
        { chat_id: String(chatId), message_id: Number(botMsgId), delete_at: deleteAt },
      ];
      if (incomingMessageId) {
        inserts.push({
          chat_id: String(chatId),
          message_id: Number(incomingMessageId),
          delete_at: deleteAt,
        });
      }
      await supabase.from('bot_ephemeral_messages').insert(inserts);
    } catch (err) {
      console.warn('Failed to schedule ephemeral message deletion in DB:', err);
    }
  }

  return data;
}

export async function answerCallbackQuery(botToken: string, queryId: string, text?: string) {
  try {
    await fetch(`https://api.telegram.org/bot${botToken}/answerCallbackQuery`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ callback_query_id: queryId, text: text || '' }),
    });
  } catch (err) {
    console.error('Failed to answer callback query:', err);
  }
}

export async function getBotChatStatus(
  botToken: string,
  chatId: string | number
): Promise<{ isAdmin: boolean; status: string; isMember: boolean }> {
  try {
    const botId = botToken.split(':')[0];
    const res = await fetch(`https://api.telegram.org/bot${botToken}/getChatMember`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, user_id: Number(botId) }),
    });
    const data = await res.json();
    if (!data.ok) {
      const desc = (data.description || '').toLowerCase();
      if (
        data.error_code === 403 ||
        desc.includes('kicked') ||
        desc.includes('not a member') ||
        desc.includes('chat not found')
      ) {
        return { isAdmin: false, status: 'kicked', isMember: false };
      }
      return { isAdmin: false, status: 'unknown', isMember: false };
    }
    const status = data.result?.status || 'unknown';
    const isMember = status === 'administrator' || status === 'creator' || status === 'member';
    return {
      isAdmin: status === 'administrator' || status === 'creator',
      status,
      isMember,
    };
  } catch {
    return { isAdmin: false, status: 'error', isMember: false };
  }
}

export async function editTelegramMessage(
  botToken: string,
  chatId: string | number,
  messageId: string | number,
  text: string,
  extraRows: any[] = []
): Promise<boolean> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/editMessageText`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: chatId,
        message_id: Number(messageId),
        text,
        parse_mode: 'HTML',
        reply_markup: extraRows.length > 0 ? { inline_keyboard: extraRows } : undefined,
      }),
    });
    const data = await res.json();
    return !!data?.ok;
  } catch (err) {
    console.warn('Failed to edit telegram message:', err);
    return false;
  }
}

export function escapeHtml(text: string): string {
  return String(text || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export function getNowInKyiv() {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Kyiv',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });
  const parts = formatter.formatToParts(now);
  const p: Record<string, string> = {};
  parts.forEach((x) => (p[x.type] = x.value));
  return {
    year: parseInt(p.year, 10),
    month: parseInt(p.month, 10),
    day: parseInt(p.day, 10),
    hour: parseInt(p.hour === '24' ? '0' : p.hour, 10),
    minute: parseInt(p.minute, 10),
  };
}

export function kyivToUtc(year: number, month: number, day: number, hour: number, minute: number): Date {
  const safeYear = Number.isInteger(year) ? year : new Date().getFullYear();
  const safeMonth = Number.isInteger(month) && month >= 1 && month <= 12 ? month : 1;
  const safeDay = Number.isInteger(day) && day >= 1 && day <= 31 ? day : 1;
  const safeHour = Number.isInteger(hour) && hour >= 0 && hour <= 23 ? hour : 10;
  const safeMinute = Number.isInteger(minute) && minute >= 0 && minute <= 59 ? minute : 0;

  const isoStr = `${safeYear}-${String(safeMonth).padStart(2, '0')}-${String(safeDay).padStart(2, '0')}T${String(safeHour).padStart(2, '0')}:${String(safeMinute).padStart(2, '0')}:00Z`;
  const targetLocalTime = new Date(isoStr).getTime();
  if (isNaN(targetLocalTime)) {
    return new Date();
  }

  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Europe/Kyiv',
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
    hour12: false,
  });
  const parts = formatter.formatToParts(new Date(isoStr));
  const p: Record<string, string> = {};
  parts.forEach((x) => (p[x.type] = x.value));
  const kyivAsUtc = Date.UTC(
    parseInt(p.year, 10),
    parseInt(p.month, 10) - 1,
    parseInt(p.day, 10),
    p.hour === '24' ? 0 : parseInt(p.hour, 10),
    parseInt(p.minute, 10),
    parseInt(p.second, 10)
  );
  const offsetMs = kyivAsUtc - targetLocalTime;
  return new Date(targetLocalTime - offsetMs);
}

export function getKyivDayRange(dayOffset = 0) {
  const now = getNowInKyiv();
  const d = new Date(Date.UTC(now.year, now.month - 1, now.day + dayOffset));
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + 1;
  const day = d.getUTCDate();

  const startUtc = kyivToUtc(y, m, day, 0, 0);
  const endUtc = kyivToUtc(y, m, day, 23, 59);
  const formattedDate = `${String(day).padStart(2, '0')}.${String(m).padStart(2, '0')}.${y}`;
  return { startIso: startUtc.toISOString(), endIso: endUtc.toISOString(), formattedDate };
}

export function tryParseQuickReminder(rawText: string): { title: string; remind_at: string } | null {
  const text = rawText.trim();
  if (text.startsWith('/')) return null;

  const now = getNowInKyiv();
  let workingText = text;

  const fullDateMatch = workingText.match(/\b(\d{1,2})[./-](\d{1,2})[./-](\d{4})\b/);
  const shortDateMatch = !fullDateMatch
    ? workingText.match(/\b(\d{1,2})[./-](\d{1,2})\b/)
    : null;

  const timeMatch = workingText.match(/\b(?:о|об\s+)?(\d{1,2}):(\d{2})\b/i);
  const hourOnlyMatch = !timeMatch
    ? workingText.match(/\b(?:о|об)\s+(\d{1,2})(?!\d|:)\b/i)
    : null;

  let hours: number | undefined;
  let minutes: number | undefined;

  if (timeMatch) {
    hours = parseInt(timeMatch[1], 10);
    minutes = parseInt(timeMatch[2], 10);
    workingText = workingText.replace(timeMatch[0], ' ');
  } else if (hourOnlyMatch) {
    hours = parseInt(hourOnlyMatch[1], 10);
    minutes = 0;
    workingText = workingText.replace(hourOnlyMatch[0], ' ');
  }

  if (hours !== undefined && (hours < 0 || hours > 23 || minutes! < 0 || minutes! > 59)) {
    return null;
  }

  const isToday = /\bсьогодні\b/i.test(workingText);
  const isTomorrow = /\bзавтра\b/i.test(workingText);
  const isDayAfter = /\bпіслязавтра\b/i.test(workingText);

  // Підтримка днів тижня (понеділок, вівторок, середа, четвер, п'ятниця, субота, неділя)
  const weekdayMatches: Record<number, RegExp> = {
    1: /\b(?:в|у)?\s*(?:понеділок|пн)\b/iu,
    2: /\b(?:у|в)?\s*(?:вівторок|вт)\b/iu,
    3: /\b(?:в|у|в|у)?\s*(?:середу|середа|ср)\b/iu,
    4: /\b(?:в|у)?\s*(?:четвер|чт)\b/iu,
    5: /\b(?:в|у|в|у)?\s*(?:п['’]?ятницю|п['’]?ятниця|пт)\b/iu,
    6: /\b(?:в|у)?\s*(?:суботу|субота|сб)\b/iu,
    0: /\b(?:в|у)?\s*(?:неділю|неділя|нд)\b/iu,
  };

  let matchedWeekday: number | null = null;
  for (const [wd, regex] of Object.entries(weekdayMatches)) {
    if (regex.test(workingText)) {
      matchedWeekday = Number(wd);
      workingText = workingText.replace(regex, ' ');
      break;
    }
  }

  // Підтримка відносного часу: "через 20 хв", "через 2 години"
  const relativeMatch = workingText.match(/\bчерез\s+(\d+)\s*(хв|хвилин|год|годин|години)\b/iu);
  if (relativeMatch) {
    const val = parseInt(relativeMatch[1], 10);
    const unit = relativeMatch[2].toLowerCase();
    const addMinutes = unit.startsWith('год') ? val * 60 : val;
    workingText = workingText.replace(relativeMatch[0], ' ');

    const title = workingText
      .replace(/(?<!\p{L})(нагадай|нагадати|\/remind|о|об)(?!\p{L})/giu, '')
      .trim()
      .replace(/\s+/g, ' ');

    const targetDate = new Date(Date.now() + addMinutes * 60 * 1000);
    return {
      title: title || 'Швидке нагадування',
      remind_at: targetDate.toISOString(),
    };
  }

  if (
    !fullDateMatch &&
    !shortDateMatch &&
    hours === undefined &&
    !isToday &&
    !isTomorrow &&
    !isDayAfter &&
    matchedWeekday === null
  ) {
    return null;
  }

  let targetYear: number;
  let targetMonth: number;
  let targetDay: number;

  if (fullDateMatch) {
    targetDay = parseInt(fullDateMatch[1], 10);
    targetMonth = parseInt(fullDateMatch[2], 10);
    targetYear = parseInt(fullDateMatch[3], 10);
    workingText = workingText.replace(fullDateMatch[0], ' ');
  } else if (shortDateMatch) {
    targetDay = parseInt(shortDateMatch[1], 10);
    targetMonth = parseInt(shortDateMatch[2], 10);
    targetYear = now.year;
    if (targetMonth < now.month || (targetMonth === now.month && targetDay < now.day)) {
      targetYear += 1;
    }
    workingText = workingText.replace(shortDateMatch[0], ' ');
  } else if (matchedWeekday !== null) {
    const curDate = new Date(Date.UTC(now.year, now.month - 1, now.day));
    const curWd = curDate.getUTCDay();
    let diff = matchedWeekday - curWd;
    if (diff <= 0) diff += 7;
    curDate.setUTCDate(curDate.getUTCDate() + diff);
    targetYear = curDate.getUTCFullYear();
    targetMonth = curDate.getUTCMonth() + 1;
    targetDay = curDate.getUTCDate();
  } else if (isDayAfter) {
    const d = new Date(Date.UTC(now.year, now.month - 1, now.day + 2));
    targetYear = d.getUTCFullYear();
    targetMonth = d.getUTCMonth() + 1;
    targetDay = d.getUTCDate();
  } else if (isTomorrow) {
    const d = new Date(Date.UTC(now.year, now.month - 1, now.day + 1));
    targetYear = d.getUTCFullYear();
    targetMonth = d.getUTCMonth() + 1;
    targetDay = d.getUTCDate();
  } else {
    const d = new Date(Date.UTC(now.year, now.month - 1, now.day));
    if (hours !== undefined) {
      if (hours < now.hour || (hours === now.hour && minutes! <= now.minute)) {
        d.setUTCDate(d.getUTCDate() + 1);
      }
    }
    targetYear = d.getUTCFullYear();
    targetMonth = d.getUTCMonth() + 1;
    targetDay = d.getUTCDate();
  }

  if (hours === undefined) {
    hours = 10;
    minutes = 0;
  }

  let title = workingText
    .replace(/(?<!\p{L})(нагадай|нагадати|\/remind|завтра|післязавтра|сьогодні|о|об)(?!\p{L})/giu, '')
    .trim()
    .replace(/\s+/g, ' ');

  if (!title) title = 'Швидке нагадування';

  const utcDate = kyivToUtc(targetYear, targetMonth, targetDay, hours, minutes!);

  return {
    title,
    remind_at: utcDate.toISOString(),
  };
}
